from pathlib import Path
p=Path(__file__).parent
s=(p/'showcase.py').read_text(encoding='utf-8')
s=s.replace("DEST=PROJECT/'out'/'strings-space_showcase_30s_4k60_20261112.mp4'", "PREVIEW='--preview' in sys.argv\nSETTINGS=json.loads((HERE/'reference-settings.json').read_text(encoding='utf-8'))\nDEST=PROJECT/'out'/'strings-space_showcase_30s_4k60_reference_v2.mp4'")
s=s.replace("if DEST.exists():", "if not PREVIEW and DEST.exists():")
s=s.replace(".replace('w,h=1920,1080','w,h=3840,2160')", ".replace('w,h=1920,1080','w,h=3840,2160')")
s=s.replace("exec(compile(setup,str(HERE/'render_check.py'),'exec'),globals())", "exec(compile(setup,str(HERE/'render_check.py'),'exec'),globals())\nG.update(SETTINGS['look']);G.update(SETTINGS['motion']);active=round(4000*G['density'])")
needle="exec(compile(render_code,str(HERE/'render_check.py'),'exec'),globals())"
replacement="""render_code=render_code.replace('uAmb=1.,uMetal=1.,uRange=.18',\"uAmb=G['ambient'],uMetal=G['metal'],uRange=.18/G['lrange']**2\")
render_code=render_code.replace('uRange=.18,uAmt=',\"uRange=.18/G['lrange']**2,uAmt=\")
render_code=render_code.replace('tuple(float(P[i]) for i in range(26,30))',\"tuple(max(0.,min(1.5,float(P[26+i])*min(G[k],1)+max(G[k]-1,0))) for i,k in enumerate(['gfloor','arch','lattice','beams']))\")
render_code=render_code.replace('uWhite=.88',\"uWhite=G['white']\")
render_code=render_code.replace('math.radians(25)',\"math.radians(G['fov']/2)\")
exec(compile(render_code,str(HERE/'render_check.py'),'exec'),globals())"""
assert needle in s;s=s.replace(needle,replacement)
s=s.replace("fflog=(HERE/'showcase-ffmpeg.log')", "fflog=(HERE/'reference-v2-ffmpeg.log')")
s=s.replace("encoder=subprocess.Popen(command,stdin=subprocess.PIPE,stderr=fflog,stdout=subprocess.DEVNULL)", "encoder=None if PREVIEW else subprocess.Popen(command,stdin=subprocess.PIPE,stderr=fflog,stdout=subprocess.DEVNULL)")
s=s.replace("Pe=P.copy();Pe[15]*=G['width']", "Pe=P.copy();Pe[15]*=G['width'];Pe[0]*=G['turb'];Pe[19]*=G['expo']*SETTINGS.get('exportExposureCompensation',[1]*9)[shot]")
s=s.replace("step(1/30)","step(G['speed']/30)")
s=s.replace("step(1/60)","step(G['speed']/60)")
s=s.replace("cd=float(P[21]);fish", "cd=float(P[21])*G['cameraDistance'];fish")
s=s.replace("light_time+=dt;camera_angle+=dt*float(P[23])", "light_time+=dt;camera_angle+=dt*float(P[23])*G['orbit']")
s=s.replace("      fade=1.", "      lights[3::4]*=G['light']\n      G['width']=.4+.08*(.5-.5*math.cos(2*math.pi*frame_index/frame_count))\n      fade=1.")
s=s.replace("      render(False)","      if PREVIEW and frame_index!=100:continue\n      render(False)")
s=s.replace("thumb.save(HERE/f'showcase-scene-{shot+1}.jpg',quality=92)","thumb.save(DELIVERY/f'reference-v2-scene-{shot+1}.jpg',quality=94)\n        if PREVIEW:Image.fromarray(pixels[::-1]).save(DELIVERY/f'reference-v2-full-{shot+1}.png')")
s=s.replace("      if frame_index>=200:", "      if PREVIEW:continue\n      if frame_index>=200:")
s=s.replace("  encoder.stdin.close();code=encoder.wait(timeout=120)", "  if encoder:encoder.stdin.close()\n  code=encoder.wait(timeout=120) if encoder else 0")
s=s.replace("  assert frames_written==1800", "  assert PREVIEW or frames_written==1800")
s=s.replace("  if encoder.poll() is None:", "  if encoder and encoder.poll() is None:")
s=s.replace("'showcase-contact-sheet.jpg'", "'reference-v2-contact-sheet.jpg'")
s=s.replace("'material':'chrome','density':3", "'material':'reference-settings.json','density':G['density'],'settings':SETTINGS")
s=s.replace("'bytes':DEST.stat().st_size", "'bytes':DEST.stat().st_size if not PREVIEW else 0")
s=s.replace("(HERE/'showcase-report.json')", "(HERE/('reference-v2-preview-report.json' if PREVIEW else 'reference-v2-report.json'))")
compile(s,'reference_showcase.py','exec')
(p/'reference_showcase.py').write_text(s,encoding='utf-8')
print('Created project-local reference exporter')
